{"implementation": "def solve(case):
    import math

    def fail(message):
        raise ValueError(message)

    def is_number(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)

    if not isinstance(case, dict):
        fail("case must be an object")

    payload = case.get("payload", case)
    if not isinstance(payload, dict):
        fail("payload must be an object")

    for key in ("nodes", "core_distance", "distances"):
        if key not in payload:
            fail("missing required field: " + key)

    nodes = payload["nodes"]
    core_input = payload["core_distance"]
    distances = payload["distances"]

    if not isinstance(nodes, list):
        fail("nodes must be a list")
    if not isinstance(core_input, dict):
        fail("core_distance must be an object")
    if not isinstance(distances, list):
        fail("distances must be a list")

    seen_nodes = set()
    for node in nodes:
        if not isinstance(node, str):
            fail("node identifiers must be strings")
        if node in seen_nodes:
            fail("duplicate node identifier: " + node)
        seen_nodes.add(node)

    if not nodes:
        fail("at least one node is required")

    if set(core_input.keys()) != seen_nodes:
        fail("core_distance keys must exactly match nodes")

    core_distance = {}
    for node in nodes:
        value = core_input[node]
        if not is_number(value) or value < 0:
            fail("invalid core distance for node: " + node)
        core_distance[node] = float(value)

    edge_by_pair = {}
    mutual_edges = []

    for index, entry in enumerate(distances):
        if not isinstance(entry, (list, tuple)) or len(entry) != 3:
            fail("distance entries must have three items")
        left, right, distance = entry
        if not isinstance(left, str) or not isinstance(right, str):
            fail("distance endpoints must be strings")
        if left not in seen_nodes or right not in seen_nodes:
            fail("distance endpoint is not registered in nodes")
        if left == right:
            fail("self distances are not valid MST edges")
        if not is_number(distance) or distance < 0:
            fail("invalid distance value")

        a, b = (left, right) if left <= right else (right, left)
        pair = (a, b)
        if pair in edge_by_pair:
            fail("duplicate undirected distance edge")
        edge_by_pair[pair] = index

        raw_distance = float(distance)
        weight = max(core_distance[a], core_distance[b], raw_distance)
        mutual_edges.append({
            "left": a,
            "right": b,
            "distance": raw_distance,
            "core_left": core_distance[a],
            "core_right": core_distance[b],
            "weight": float(weight),
            "source_index": index,
        })

    mutual_edges.sort(key=lambda edge: (edge["weight"], edge["left"], edge["right"]))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    def union(left, right):
        root_left = find(left)
        root_right = find(right)
        if root_left == root_right:
            return False
        if rank[root_left] < rank[root_right]:
            parent[root_left] = root_right
        elif rank[root_left] > rank[root_right]:
            parent[root_right] = root_left
        else:
            if root_left <= root_right:
                parent[root_right] = root_left
                rank[root_left] += 1
            else:
                parent[root_left] = root_right
                rank[root_right] += 1
        return True

    selected_edges = []
    for edge in mutual_edges:
        if union(edge["left"], edge["right"]):
            selected_edges.append(dict(edge))
            if len(selected_edges) == len(nodes) - 1:
                break

    if len(selected_edges) != len(nodes) - 1:
        fail("distance graph is disconnected")

    total_weight = sum(edge["weight"] for edge in selected_edges)

    return {
        "core_distance": {node: core_distance[node] for node in nodes},
        "mutual_reachability": mutual_edges,
        "mst_edges": selected_edges,
        "total_weight": float(total_weight),
    }
